 var pick=[ns[0],ns[1]];
 for(var i=0;i<Math.min(4,ns.length);i++)for(var j=i+1;j<Math.min(4,ns.length);j++)if(dist({c:ns[i][0],r:ns[i][1]},{c:ns[j][0],r:ns[j][1]})===1){pick=[ns[i],ns[j]];i=9;break}
 pick.forEach(function(p){if(p){var dg=spawn('ft',1,p[0],p[1]);dg.th=0}});draw();
